using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public sealed class ConfigResources
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxConnections = 100,
            Features = new { DarkMode = true, BetaApi = false },
            Version = "2.1.0"
        };
        return JsonSerializer.Serialize(config, JsonOptions);
    }

    [McpServerResource(UriTemplate = "config://app/regions", Name = "regions",
        Title = "Supported Regions", MimeType = "application/json")]
    public static string GetRegions()
    {
        var regions = new[] { "us-east-1", "us-west-2", "eu-west-1", "ap-southeast-1" };
        return JsonSerializer.Serialize(regions, JsonOptions);
    }
}

